choose.when:
SELECT coupon_id AS couponId, unit_id AS unitId
FROM paid_coupon_available_unit
WHERE coupon_id = #{items[0].couponId}
ORDER BY unit_id
LIMIT #{items[0].quantity}
FOR UPDATE SKIP LOCKED

otherwise.foreach:
(SELECT coupon_id AS couponId, unit_id AS unitId
 FROM paid_coupon_available_unit
 WHERE coupon_id = #{item.couponId}
 ORDER BY unit_id
 LIMIT #{item.quantity}
 FOR UPDATE SKIP LOCKED)

mapper.sql:
SELECT coupon_id AS couponId, unit_id AS unitId
FROM paid_coupon_available_unit
WHERE coupon_id = #{scan.couponId}

    AND unit_id >= #{scan.fromUnitId}


    AND unit_id < #{scan.belowUnitId}

ORDER BY unit_id
LIMIT #{scan.quantity}
FOR UPDATE SKIP LOCKED

mapper.delete:
DELETE FROM paid_coupon_reserved_unit
WHERE request_id IN

    #{requestId}

mapper.select:
SELECT request_id AS requestId, coupon_id AS couponId, CAST(COUNT(*) AS SIGNED) AS quantity FROM paid_coupon_reserved_unit WHERE request_id IN
#{requestId}
GROUP BY request_id, coupon_id ORDER BY request_id, coupon_id
